__global__ void square_matrix_mul_kernel_shmem_optimized(const float* A, const float* B, float* C, int N) {
    // block size is 16x16
    const int BLOCK_SIZE = 16;
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE]; // Bs will be stored transposed

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float C_val = 0.0f;

    // iterate over tiles
    for (int tile = 0; tile < (N + BLOCK_SIZE - 1) / BLOCK_SIZE; ++tile) {
        // load tile of A into shared memory
        int A_row_global = row;
        int A_col_global = tile * BLOCK_SIZE + threadIdx.x;
        if (A_row_global < N && A_col_global < N) {
            As[threadIdx.y][threadIdx.x] = A[A_row_global * N + A_col_global];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // load tile of B into shared memory, transposing it
        int B_row_global = tile * BLOCK_SIZE + threadIdx.y; // original row of B
