    // block size is 16x16
    const int BLOCK_SIZE = 16;
    const int TILE_WIDTH = 16;
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE + 1]; // +1 for padding to avoid bank conflicts
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE + 1]; // +1 for padding to avoid bank conflicts

    int row = blockIdx.y * TILE_WIDTH + threadIdx.y;
    int col = blockIdx.x * TILE_WIDTH + threadIdx.x;

    float C_val = 0.0f;

    // iterate over tiles
    for (int tile = 0; tile < (N + TILE_WIDTH - 1) / TILE_WIDTH; ++tile) {
        // load tile of A into shared memory
        int A_row_global = row;
        int A_col_global = tile * TILE_WIDTH + threadIdx.x;
        if (A_row_global < N && A_col_global < N) {
            As[threadIdx.y][threadIdx.x] = A[A_row_global * N + A_col_global];
